on conflict (activity_type, pool_week) do nothing;

update public.premium_arcade_content_pools p set items = p.items || coalesce((
  select jsonb_agg(n.value order by n.ordinality) from jsonb_array_elements($q$[{"id":"s-multiply-by-11","topic":"multiplying by 11","prompt":{"en":"What is 34 × 11?","lo":"34 × 11 ເທົ່າໃດ?"},"options":[{"en":"374","lo":"374"},{"en":"364","lo":"364"},{"en":"384","lo":"384"},{"en":"354","lo":"354"}],"answerIndex":0,"explanation":{"en":"To multiply a two-digit number by 11, add the digits and place the sum between them: 3 + 4 = 7, so 374.","lo":"ເພື່ອຄູນຕົວເລກສອງຕົວໂດຍ 11, ນຳເອົາຕົວເລກມາບວກກັນ ແລະ ໃສ່ຜົນບວກລະຫວ່າງພວກມັນ: 3 + 4 = 7, ດັ່ງນັ້ນໄດ້ 374."}},{"id":"s-square-numbers-ending-in-5","topic":"square numbers ending in 5","prompt":{"en":"What is 25²?","lo":"25² ເທົ່າໃດ?"},"options":[{"en":"625","lo":"625"},{"en":"615","lo":"615"},{"en":"635","lo":"635"},{"en":"645","lo":"645"}],"answerIndex":0,"explanation":{"en":"To square a number ending in 5, multiply the first digit by itself plus one, then add 25: 2 × 3 = 6, so 625.","lo":"ເພື່ອຂັ້ນສູງຕົວເລກທີ່ສິ້ນດ້ວຍ 5, ນຳເອົາຕົວເລກຕົ້ນມາຄູນກັບຕົວເລກຕົ້ນບວກ 1, ແລ້ວເພີ່ມ 25: 2 × 3 = 6, ດັ່ງນັ້ນໄດ້ 625."}},{"id":"s-quick-percentages","topic":"quick percentages","prompt":{"en":"What is 10% of 180?","lo":"10% ຂອງ 180 ເທົ່າໃດ?"},"options":[{"en":"18","lo":"18"},{"en":"19","lo":"19"},{"en":"17","lo":"17"},{"en":"20","lo":"20"}],"answerIndex":0,"explanation":{"en":"To find 10%, move the decimal point one place left: 180 becomes 18.","lo":"ເພື່ອຊອກຫາ 10%, ເລື່ອນຈຸດທິດຕາມໄປໜ້າໜຶ່ງຕົວ: 180 ຕົກເປັນ 18."}},{"id":"s-divisibility-rule-for-3","topic":"divisibility rule for 3","prompt":{"en":"Is 546 divisible by 3?","lo":"546 ສາມາດແບ່ງຢ່າງເປັນເອກະລັກດ້ວຍ 3 ໄດ້ບໍ?"},"options":[{"en":"Yes","lo":"ແມ່ນ"},{"en":"No","lo":"ບໍ່"},{"en":"Maybe","lo":"ອາດ"},{"en":"Not sure","lo":"ບໍ່ແນ່"}],"answerIndex":0,"explanation":{"en":"A number is divisible by 3 if the sum of its digits is divisible by 3: 5 + 4 + 6 = 15, and 15 ÷ 3 = 5.","lo":"ຕົວເລກແມ່ນຖືກແບ່ງດ້ວຍ 3 ຖ້າຈຳນວນຕົວເລກບວກກັນໄດ້ຄາດເດັດດ້ວຍ 3: 5 + 4 + 6 = 15, ແລະ 15 ÷ 3 = 5."}},{"id":"s-multiply-by-15","topic":"multiply by 15","prompt":{"en":"What is 24 × 15?","lo":"24 × 15 ເທົ່າໃດ?"},"options":[{"en":"360","lo":"360"},{"en":"350","lo":"350"},{"en":"370","lo":"370"},{"en":"340","lo":"340"}],"answerIndex":0,"explanation":{"en":"To multiply by 15, multiply by 10 and add half of that result: 24 × 10 = 240, half is 120, so 240 + 120 = 360.","lo":"ເພື່ອຄູນດ້ວຍ 15, ຄູນດ້ວຍ 10 ແລ້ວເພີ່ມເຄື່ອງຈັກເຄື່ອງນັ້ນຄາດເດັດ: 24 × 10 = 240, ເຄື່ອງຈັກເຄື່ອງນັ້ນຄາດເດັດແມ່ນ 120, ດັ່ງນັ້ນ 240 + 120 = 360."}},{"id":"s-past-tense-verb-with-yesterday","topic":"past tense with 'yesterday'","prompt":{"en":"Choose the correct verb form: 'She ___ to school yesterday.'","lo":"ເລືອກຮູບແບບຄຳກິລິຍາທີ່ຖືກຕ້ອງ: 'She ___ to school yesterday.'"},"options":[{"en":"goes","lo":"goes"},{"en":"went","lo":"went"},{"en":"going","lo":"going"},{"en":"will go","lo":"will go"}],"answerIndex":1,"explanation":{"en":"Use 'went' because 'yesterday' indicates past tense.","lo":"ໃຊ້ 'ໄປ' ເພາະ 'ມື້ວານນີ້' ບອກວ່າເປັນອະດີດ."}},{"id":"s-preposition-of-place-in-the-library","topic":"preposition of place: in the library","prompt":{"en":"Choose the correct preposition: 'The book is ___ the shelf.'","lo":"ເລືອກຄຳບຸບພະບົດທີ່ຖືກຕ້ອງ: 'The book is ___ the shelf.'"},"options":[{"en":"on","lo":"on"},{"en":"in","lo":"in"},{"en":"under","lo":"under"},{"en":"behind","lo":"behind"}],"answerIndex":0,"explanation":{"en":"Use 'on' because the book is physically on top of the shelf.","lo":"ໃຊ້ 'ເທິງ' ເພາະປຶ້ມຢູ່ເທິງລົດຂອງຢ່າງເປັນຈິງ."}},{"id":"s-article-before-university","topic":"article before 'university'","prompt":{"en":"Choose the correct article: 'She studies at ___ university.'","lo":"ເລືອກຄຳບຸບພະບົດທີ່ຖືກຕ້ອງ: 'She studies at ___ university.'"},"options":[{"en":"a","lo":"a"},{"en":"an","lo":"an"},{"en":"the","lo":"the"},{"en":"no article","lo":"no article"}],"answerIndex":0,"explanation":{"en":"Use 'a' because 'university' starts with a consonant sound.","lo":"ໃຊ້ 'ໜຶ່ງ' ເພາະ 'ສະຖາບັນສູງ' ດ້ວຍສຽງສະຫວັດ."}},{"id":"s-conditional-type-2-if-she-were","topic":"conditional type 2: if she were","prompt":{"en":"Choose the correct conditional: 'If she ___ rich, she would travel.'","lo":"ເລືອກຂໍ້ມູນເງື່ອນໄຂທີ່ຖືກຕ້ອງ: 'If she ___ rich, she would travel.'"},"options":[{"en":"is","lo":"is"},{"en":"were","lo":"were"},{"en":"was","lo":"was"},{"en":"will be","lo":"will be"}],"answerIndex":1,"explanation":{"en":"Use 'were' in second conditionals for hypothetical situations.","lo":"ໃຊ້ 'ເປັນ' ໃນຂໍ້ມູນເງື່ອນໄຂທີສອງ ເພື່ອສະແດງສະຖານະທີ່ບໍ່ເປັນຈິງ."}},{"id":"s-word-order-in-question-with-do","topic":"word order in question with 'do'","prompt":{"en":"Choose the correct word order: '___ you like coffee?'","lo":"ເລືອກການຈັດຕຳແໜ່ງຄຳທີ່ຖືກຕ້ອງ: '___ you like coffee?'"},"options":[{"en":"Do","lo":"Do"},{"en":"Did","lo":"Did"},{"en":"Are","lo":"Are"},{"en":"Have","lo":"Have"}],"answerIndex":0,"explanation":{"en":"Use 'Do' because the sentence is about a general habit in present time.","lo":"ໃຊ້ 'ເຮັດ' ເພາະປະໂຫຍກກ່ຽວກັບການເຮັດເປັນນິສັຍທີ່ເປັນປັດຈຸບັນ."}},{"id":"s-word-meaning-ambiguous-words","topic":"word meaning: ambiguous words","prompt":{"en":"What does 'light' mean in this sentence? 'The light in the room is too bright.'","lo":"‘Light’ ໃນຂໍ້ຄວາມນີ້ໝາຍເຖິງຫຍັງ? 'ແສງໃນຫໍພັກເຂັ້ມເກີນໄປ.'"},"options":[{"en":"not heavy","lo":"ບໍ່ໜັກ"},{"en":"bright illumination","lo":"ແສງທີ່ເຂັ້ມ"},{"en":"a small lamp","lo":"ໄຟລົດນ້ອຍ"},{"en":"a color","lo":"ສີໜຶ່ງ"}],"answerIndex":1,"explanation":{"en":"In this context, 'light' refers to brightness, not weight.","lo":"ໃນຂໍ້ຄວາມນີ້, ‘light’ ຄືແສງທີ່ເຂັ້ມ, ບໍ່ໄດ້ໝາຍເຖິງນ້ຳໜັກ."}},{"id":"s-phrasal-verb-get-up","topic":"phrasal verb: get up","prompt":{"en":"Which sentence uses 'get up' correctly?","lo":"ຂໍ້ຄວາມໃດໃນຕໍ່ໄປນີ້ໃຊ້ 'get up' ເທື່ອ?"},"options":[{"en":"I get up at 6 a.m. every day.","lo":"ຂ້ອຍຕື່ມຕົວເວລາ 6 ໂມງເຊົ້າທຸກໆມື້."},{"en":"She gets up the stairs slowly.","lo":"ນາງຕື່ມຕົວຂຶ້ນໄປເທິງຂັ້ນໄດ້ຊ້າ."},{"en":"They got up a new plan.","lo":"ພວກເຂົາຕື່ມໂປຣແກຣມໃໝ່."},{"en":"He gets up early for work.","lo":"ເຂົາຕື່ມຕົວກ່ອນເວລາເຮັດວຽກ."}],"answerIndex":0,"explanation":{"en":"'Get up' means to rise from bed, not to create or climb.","lo":"'Get up' ໝາຍເຖິງການຕື່ມຕົວຈາກເຕົາ, ບໍ່ໄດ້ໝາຍເຖິງການສ້າງ ຫຼື ການຂຶ້ນຂັ້ນ."}},{"id":"s-collocation-technical-innovation","topic":"collocation: technical innovation","prompt":{"en":"Which phrase is a natural collocation with 'AI'?","lo":"ຂໍ້ຄວາມໃດທີ່ເປັນການຈັບຄູ່ທີ່ແທ້ຈິງກັບ 'AI'?"},"options":[{"en":"AI development","lo":"ການພັດທະນາ AI"},{"en":"AI solution","lo":"ແບບແຜນ AI"},{"en":"AI problem","lo":"ບັນຫາ AI"},{"en":"AI mistake","lo":"ຂໍ້ຜິດ AI"}],"answerIndex":0,"explanation":{"en":"'AI development' is a common and natural collocation.","lo":"'AI development' ແມ່ນການຈັບຄູ່ທີ່ເປັນທີ່ນິຍົມແລະເປັນທຳມະດາ."}},{"id":"s-idiom-take-on-challenge","topic":"idiom: take on challenge","prompt":{"en":"What does 'take on a challenge' mean?","lo":"‘Take on a challenge’ ໝາຍເຖິງຫຍັງ?"},"options":[{"en":"to avoid difficulty","lo":"ຫຼີກລ່ຽງຄວາມຍາກ"},{"en":"to accept a difficult task","lo":"ຮັບເອົາວຽກຍາກ"},{"en":"to complain about work","lo":"ບັນທຶກການເຮັດວຽກ"},{"en":"to start a new job","lo":"ເລີ່ມວຽກໃໝ່"}],"answerIndex":1,"explanation":{"en":"'Take on a challenge' means to willingly accept a hard task.","lo":"'Take on a challenge' ໝາຍເຖິງການຮັບເອົາວຽກຍາກດ້ວຍຄວາມຕັ້ງໃຈ."}},{"id":"s-commonly-confused-words-sight-serve","topic":"confused words: sight vs serve","prompt":{"en":"Choose the correct word: 'Please ___ the food to the guests.'","lo":"ເລືອກຄຳທີ່ຖືກຕ້ອງ: 'Please ___ the food to the guests.'"},"options":[{"en":"sight","lo":"sight"},{"en":"serve","lo":"serve"},{"en":"site","lo":"site"},{"en":"cite","lo":"cite"}],"answerIndex":1,"explanation":{"en":"'Serve' means to provide food or help, which fits the context.","lo":"'Serve' ໝາຍເຖິງການນຳເອົາອາຫານ ຫຼື ການຊ່ວຍ, ເໝາະກັບຂໍ້ຄວາມ."}}]$q$::jsonb) with ordinality n
  where not exists (select 1 from jsonb_array_elements(p.items) e where lower(e->'prompt'->>'en') = lower(n.value->'prompt'->>'en'))
), '[]'::jsonb)
where p.activity_type = 'brain_sprint' and p.pool_week = $q$2026-10-19$q$::date;

update public.premium_arcade_content_pools p set items = p.items || coalesce((
  select jsonb_agg(n.value order by n.ordinality) from jsonb_array_elements($q$[{"id":"s-browser","english":"browser","lao":"ເວັບໄຊເບີຣ໌ເຊີ"},{"id":"s-download","english":"download","lao":"ດາວໂຫຼດ"},{"id":"s-upload","english":"upload","lao":"ອັບໂຫຼດ"},{"id":"s-website","english":"website","lao":"ເວັບໄຊ"},{"id":"s-password","english":"password","lao":"ລະຫັດຜ່ານ"},{"id":"s-username","english":"username","lao":"ຊື່ຜູ້ໃຊ້"},{"id":"s-link","english":"link","lao":"ລິ້ງ"},{"id":"s-ecosystem","english":"ecosystem","lao":"ລະບົບນິເວດ"},{"id":"s-photosynthesis","english":"photosynthesis","lao":"ການສັງເຄາະດ້ວຍແສງ"},{"id":"s-habitat","english":"habitat","lao":"ຖິ່ນອາໄສ"},{"id":"s-predator","english":"predator","lao":"ສັດນັກລ່າ"},{"id":"s-prey","english":"prey","lao":"ເຫຍື່ອ"},{"id":"s-decomposer","english":"decomposer","lao":"ຈຸລິນທີ່ຍ່ອຍສະເລ່ຍ"},{"id":"s-biodiversity","english":"biodiversity","lao":"ຄວາມຫຼາກຫຼາຍທາງຊີວະພາບ"}]$q$::jsonb) with ordinality n
  where not exists (select 1 from jsonb_array_elements(p.items) e
    where lower(e->>'english') = lower(n.value->>'english') or e->>'lao' = n.value->>'lao')
), '[]'::jsonb)
where p.activity_type = 'word_match' and p.pool_week = $q$2026-10-19$q$::date;
